 const filterButtons = document.querySelectorAll("[data-filter]");
 const productCards = document.querySelectorAll(".product-card");
 const cartCountElement = document.querySelector("[data-cart-count]");
 const statusMessage = document.querySelector("[data-status-message]");
 const addToCartButtons = document.querySelectorAll(".product-card__action");
 const countdownElement = document.querySelector("[data-countdown]");
 const cartButton = document.querySelector(".cart-button");

 let cartCount = 0;
 let remainingSeconds = 18 * 60 * 60;

 const updateCountdown = () => {
   if (!countdownElement) {
     return;
   }

   const hours = String(Math.floor(remainingSeconds / 3600)).padStart(2, "0");
   const minutes = String(Math.floor((remainingSeconds % 3600) / 60)).padStart(2, "0");
   const seconds = String(remainingSeconds % 60).padStart(2, "0");

   countdownElement.textContent = `${hours}:${minutes}:${seconds}`;
   remainingSeconds = remainingSeconds > 0 ? remainingSeconds - 1 : 0;
 };

 filterButtons.forEach((button) => {
   button.addEventListener("click", () => {
     const selectedFilter = button.dataset.filter;

     filterButtons.forEach((chip) => {
       const isActive = chip === button;
       chip.classList.toggle("is-active", isActive);
       chip.setAttribute("aria-pressed", String(isActive));
     });

     let visibleCount = 0;

     productCards.forEach((card) => {
       const matches = selectedFilter === "all" || card.dataset.category === selectedFilter;
       card.classList.toggle("is-hidden", !matches);

       if (matches) {
         visibleCount += 1;
       }
     });

     if (statusMessage) {
       const label = button.textContent?.trim() || "selected";
       statusMessage.textContent = `${visibleCount} featured products shown for ${label}.`;
     }
   });
 });

 addToCartButtons.forEach((button) => {
   button.addEventListener("click", () => {
     cartCount += 1;
     const productName = button.dataset.productName || "Item";

     if (cartCountElement) {
       cartCountElement.textContent = String(cartCount);
     }

     if (cartButton) {
       cartButton.setAttribute("aria-label", `Cart with ${cartCount} items`);
     }

     if (statusMessage) {
       statusMessage.textContent = `${productName} added to cart.`;
     }
   });
 });

 updateCountdown();
 window.setInterval(updateCountdown, 1000);

