969.   }
970. 
971.   const hours = String(Math.floor(remainingSeconds / 3600)).padStart(2, "0");
972.   const minutes = String(Math.floor((remainingSeconds % 3600) / 60)).padStart(2, "0");
973.   const seconds = String(remainingSeconds % 60).padStart(2, "0");
